import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { useLoadScript, Autocomplete } from "@react-google-maps/api";
import MapComponent from "../MapComponent";
import "./LandPredictionForm.css";

const libraries = ["places"];

export default function LandPredictionForm() {
  const navigate = useNavigate();

  const { isLoaded, loadError } = useLoadScript({
    googleMapsApiKey: process.env.REACT_APP_GOOGLE_MAPS_API_KEY,
    libraries,
  });

  const [form, setForm] = useState({
    location: "",
    area: "",
    zoning: "",
    roadAccess: "",
    utilities: "",
    soilType: "",
    developmentPotential: "",
    cityDistance: "",
  });

  const [coordinates, setCoordinates] = useState({ lat: null, lng: null });
  const [locationOptions, setLocationOptions] = useState([]);
  const [autocomplete, setAutocomplete] = useState(null);
  const [result, setResult] = useState();
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const onLoad = (autoC) => setAutocomplete(autoC);

  const onPlaceChanged = () => {
    if (autocomplete !== null) {
      const place = autocomplete.getPlace();
      if (!place.geometry) {
        alert("Please select a location from the dropdown suggestions.");
        return;
      }
      const formattedAddress = place.formatted_address || "";
      setForm((form) => ({ ...form, location: formattedAddress }));
      setCoordinates({
        lat: place.geometry.location.lat(),
        lng: place.geometry.location.lng(),
      });
      setLocationOptions([]);
    }
  };

  const fetchGeocodeOptions = async (latitude, longitude) => {
    const geoApiKey = process.env.REACT_APP_GOOGLE_MAPS_API_KEY;
    try {
      const resp = await fetch(
        `https://maps.googleapis.com/maps/api/geocode/json?latlng=${latitude},${longitude}&key=${geoApiKey}`
      );
      const data = await resp.json();
      if (data.status === "OK") {
        const options = data.results.map((res, idx) => ({
          label: res.formatted_address,
          value: idx,
          location: res.geometry.location,
        }));
        setLocationOptions(options);
        setForm((form) => ({ ...form, location: options[0].label }));
        setCoordinates({
          lat: options[0].location.lat,
          lng: options[0].location.lng,
        });
      } else {
        alert(`Failed to get address: ${data.status} - ${data.error_message || ""}`);
      }
    } catch (error) {
      console.error(error);
      alert("Error fetching location address.");
    }
  };

  const onLocationSelectionChange = (e) => {
    const selectedIdx = e.target.value;
    const selectedOption = locationOptions[selectedIdx];
    if (selectedOption) {
      setForm((form) => ({ ...form, location: selectedOption.label }));
      setCoordinates({
        lat: selectedOption.location.lat,
        lng: selectedOption.location.lng,
      });
    }
  };

  const getCurrentLocation = () => {
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          const { latitude, longitude } = position.coords;
          fetchGeocodeOptions(latitude, longitude);
        },
        () => alert("Permission denied or unable to get location."),
        { enableHighAccuracy: true }
      );
    } else {
      alert("Geolocation is not supported by your browser.");
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setResult(undefined);
    setLoading(true);
    try {
      const response = await fetch(`${process.env.REACT_APP_BACKEND_URL}/predict/land`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });
      const data = await response.json();
      setResult(data.price);
    } catch (error) {
      console.error("Prediction error:", error);
      setResult("Prediction failed.");
    }
    setLoading(false);
  };

  if (loadError) return <div>Error loading maps</div>;
  if (!isLoaded) return <div>Loading Maps...</div>;

  return (
    <div className="land-predict-root">
      <button className="back-btn" onClick={() => navigate("/")}>
        ← Back to Home
      </button>
      <div className="land-predict-panels">
        <div className="land-details-card">
          <div className="details-header">
            <span className="icon">
              <img src="/icons/land.png" alt="" />
            </span>
            <span className="details-title">Land Details</span>
          </div>
          <div className="details-desc">Enter the details of the land to get an accurate price prediction</div>
          <form onSubmit={handleSubmit} className="details-form">
            <div className="form-group">
              <label className="form-label">Location</label>
              <div className="input-with-icon">
                <span className="input-icon">📍</span>
                <Autocomplete onLoad={onLoad} onPlaceChanged={onPlaceChanged}>
                  <input
                    name="location"
                    type="text"
                    placeholder="e.g., County, City, District"
                    value={form.location}
                    onChange={handleChange}
                    required
                    style={{ width: "300px", padding: "8px" }}
                  />
                </Autocomplete>
                <button type="button" className="location-btn" onClick={getCurrentLocation}>
                  Use My Location
                </button>
              </div>
            </div>

            {locationOptions.length > 1 && (
              <div className="form-group">
                <label htmlFor="locationSelect">Select precise location:</label>
                <select id="locationSelect" onChange={onLocationSelectionChange}>
                  {locationOptions.map((option, idx) => (
                    <option key={idx} value={idx}>
                      {option.label}
                    </option>
                  ))}
                </select>
              </div>
            )}

            <div className="form-row">
              <div className="form-group">
                <label className="form-label">Area (acres)</label>
                <input
                  name="area"
                  type="number"
                  min="0"
                  step="0.1"
                  placeholder="2.5"
                  value={form.area}
                  onChange={handleChange}
                  required
                />
              </div>
              <div className="form-group">
                <label className="form-label">Zoning Type</label>
                <select name="zoning" value={form.zoning} onChange={handleChange} required>
                  <option value="">Select zoning</option>
                  <option>Agricultural</option>
                  <option>Residential</option>
                  <option>Commercial</option>
                  <option>Industrial</option>
                  <option>Conservation</option>
                </select>
              </div>
            </div>

            {/* Add other input fields as needed */}

            <button className="predict-btn" type="submit" disabled={loading}>
              {loading ? "Predicting..." : "Predict Land Price"}
            </button>
          </form>

          {coordinates.lat && coordinates.lng && <MapComponent lat={coordinates.lat} lng={coordinates.lng} />}
        </div>

        <div className="price-prediction-card">
          <div className="price-header">
            <span className="price-icon"> ₹</span>
            <span className="price-title">Price Prediction</span>
          </div>
          <div className="price-desc">Your estimated land price will appear here</div>
          <div className="price-output">
            {!!result ? (
              <div className="price-result">
                <span className="result-value">₹ {result}</span>
              </div>
            ) : (
              <div className="result-placeholder">
                <span className="result-calc-icon">🧮</span>
                <span>Fill out the form to see your price prediction</span>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
